  label = EXCLUDED.label, parent_code = EXCLUDED.parent_code, sort = EXCLUDED.sort, updated_at = now();

-- 旧版自定义行业码停用（只停用不删除）
UPDATE dct_taxonomy_option SET status = 0, updated_at = now()
WHERE dimension = 'industry' AND (code LIKE '%.%' OR code ~ '^[A-Z]{2,}$');

COMMIT;
